  1	import type { RichTextBlock, RichTextList, RichTextListItem, RichTextSpan } from './rich-text-blocks.model';
  2	
  3	/**
  4	 * Boundary parser of Strapi `blocks` (ADR-0009). Pure: no Angular. The value is `unknown` until
  5	 * checked; only the whitelisted tree comes out. Unsupported formatting degrades or is dropped with
  6	 * a `console.warn` that names the node type or the problem, never text, a URL or a file name.
  7	 */
  8	
  9	const MAX_LIST_DEPTH = 6;
 10	const SHORT_IDENTIFIER = /^[a-z-]{1,32}$/;
 11	
 12	type Wire = Record<string, unknown>;
 13	const isRec = (v: unknown): v is Wire => typeof v === 'object' && v !== null && !Array.isArray(v);
 14	const isBlank = (spans: readonly RichTextSpan[]): boolean => spans.every((s) => s.text.trim() === '');
 15	
 16	/** The node type for a warning: a short identifier as is, anything else "unknown" (it may be markup). */
 17	function typeName(node: unknown): string {
 18	  const type = isRec(node) ? node['type'] : undefined;
 19	  return typeof type === 'string' && SHORT_IDENTIFIER.test(type) ? type : 'unknown';
 20	}
 21	
 22	function warn(what: string): void {
 23	  console.warn(`rich text: ${what}`);
 24	}
 25	
 26	/** The spans of the inline children of a block; links keep their text only. */
 27	function parseInline(children: unknown[], insideLink = false): RichTextSpan[] {
 28	  const spans: RichTextSpan[] = [];
 29	  for (const child of children) {
 30	    if (isRec(child) && child['type'] === 'text') {
 31	      if (typeof child['text'] !== 'string') {
 32	        warn('text');
 33	        continue;
 34	      }
 35	      spans.push({
 36	        text: child['text'],
 37	        bold: child['bold'] === true,
 38	        italic: child['italic'] === true,
 39	        underline: child['underline'] === true,
 40	        strikethrough: child['strikethrough'] === true,
 41	      });
 42	    } else if (isRec(child) && child['type'] === 'link') {
 43	      if (insideLink) {
 44	        // A link inside a link is not a supported shape: dropped, so recursion stops at one level.
 45	        warn('link-depth');
 46	        continue;
 47	      }
 48	      warn('link');
 49	      if (Array.isArray(child['children'])) {
 50	        for (const inner of parseInline(child['children'], true)) spans.push(inner);
 51	      }
 52	    } else {
 53	      warn(typeName(child));
 54	    }
 55	  }
 56	  return spans;
 57	}
 58	
 59	function parseList(node: Wire, depth: number): RichTextList | null {
 60	  const format = node['format'];
 61	  if ((format !== 'ordered' && format !== 'unordered') || !Array.isArray(node['children'])) {
 62	    warn('list');
 63	    return null;
 64	  }
 65	  const items: RichTextListItem[] = [];
 66	  // The item a following nested list attaches to; null when none, or the item was dropped.
 67	  let last: RichTextListItem | null = null;
 68	  for (const child of node['children']) {
 69	    if (isRec(child) && child['type'] === 'list') {
 70	      if (depth >= MAX_LIST_DEPTH) {
 71	        warn('list-depth');
 72	        continue;
 73	      }
 74	      const nested = parseList(child, depth + 1);
 75	      if (!nested) continue;
 76	      if (!last) {
 77	        last = { spans: [], lists: [] };
 78	        items.push(last);
 79	      }
 80	      last.lists.push(nested);
 81	    } else if (isRec(child) && child['type'] === 'list-item' && Array.isArray(child['children'])) {
 82	      const spans = parseInline(child['children']);
 83	      if (isBlank(spans)) {
 84	        last = null;
 85	        continue;
 86	      }
 87	      last = { spans, lists: [] };
 88	      items.push(last);
 89	    } else {
 90	      warn(typeName(child));
 91	    }
 92	  }
 93	  return items.length > 0 ? { ordered: format === 'ordered', items } : null;
 94	}
 95	
 96	interface RawHeading {
 97	  level: number;
 98	  spans: RichTextSpan[];
 99	}
100	
101	/** `null` when the whole body is malformed: not an array, or no text left after the rules. */
102	export function parseRichTextBlocks(value: unknown): RichTextBlock[] | null {
103	  if (!Array.isArray(value)) {
104	    warn('body');
105	    return null;
106	  }
107	  // Headings are collected with their level; depth is relative to the smallest level kept.
108	  const pending: (RichTextBlock | RawHeading)[] = [];
109	  for (const node of value) {
110	    if (!isRec(node)) {
111	      warn(typeName(node));
112	      continue;
113	    }
114	    const type = node['type'];
115	    const children = node['children'];
116	    if (type === 'list') {
117	      const list = parseList(node, 1);
118	      if (list) pending.push({ kind: 'list', list });
119	    } else if (type === 'paragraph' || type === 'quote' || type === 'code' || type === 'heading') {
120	      if (!Array.isArray(children)) {
121	        warn(typeName(node));
122	        continue;
123	      }
124	      const level = node['level'];
125	      if (type === 'heading' && !(typeof level === 'number' && Number.isInteger(level) && level >= 1 && level <= 6)) {
126	        warn('heading');
127	        continue;
128	      }
129	      if (type === 'quote' || type === 'code') warn(type);
130	      const spans = parseInline(children);
131	      if (isBlank(spans)) continue;
132	      pending.push(type === 'heading' ? { level: level as number, spans } : { kind: 'paragraph', spans });
133	    } else {
134	      warn(typeName(node));
135	    }
136	  }
137	  let smallest = Infinity;
138	  for (const b of pending) if ('level' in b && b.level < smallest) smallest = b.level;
139	  if (smallest === Infinity) smallest = 1;
140	  const blocks: RichTextBlock[] = pending.map((b) => ('level' in b ? { kind: 'heading', depth: b.level - smallest, spans: b.spans } : b));
141	  if (blocks.length === 0) {
142	    warn('body');
143	    return null;
144	  }
145	  return blocks;
146	}
  1	import { parseRichTextBlocks } from './rich-text-blocks';
  2	import type { Terms } from './terms.model';
  3	
  4	const isRec = (v: unknown): v is Record<string, unknown> => typeof v === 'object' && v !== null && !Array.isArray(v);
  5	
  6	interface Candidate {
  7	  terms: Terms;
  8	  publishedAt: number;
  9	}
 10	
 11	function parseItem(raw: unknown): Candidate | null {
 12	  if (!isRec(raw)) {
 13	    console.warn('terms: an entry was skipped (item)');
 14	    return null;
 15	  }
 16	  const title = raw['title'];
 17	  if (typeof title !== 'string' || title.trim() === '') {
 18	    console.warn('terms: an entry was skipped (title)');
 19	    return null;
 20	  }
 21	  const published = raw['publishedAt'];
 22	  const instant = typeof published === 'string' ? Date.parse(published) : NaN;
 23	  if (Number.isNaN(instant)) {
 24	    console.warn('terms: an entry was skipped (publishedAt)');
 25	    return null;
 26	  }
 27	  const blocks = parseRichTextBlocks(raw['body']);
 28	  if (blocks === null) {
 29	    console.warn('terms: an entry was skipped (body)');
 30	    return null;
 31	  }
 32	  return { terms: { title, blocks }, publishedAt: instant };
 33	}
 34	
 35	/**
 36	 * Boundary validation and selection of the terms response (spec 7.2): the most recently published
 37	 * well-formed entry (the server sort is not trusted), or `null` when there is none. Warnings name
 38	 * the problem, never the text. Throws when the body is not a list at all (the page then shows its
 39	 * error state).
 40	 */
 41	export function parseTerms(body: unknown): Terms | null {
 42	  const data = isRec(body) ? body['data'] : null;
 43	  if (!Array.isArray(data)) throw new Error('terms: unexpected response shape');
 44	  const candidates = data.map(parseItem).filter((c): c is Candidate => c !== null);
 45	  if (candidates.length > 1) console.warn('terms: more than one published entry for the country, the most recent is shown');
 46	  candidates.sort((a, b) => b.publishedAt - a.publishedAt);
 47	  return candidates[0]?.terms ?? null;
 48	}

