import { parseTerms } from './terms.mjs';
const warns = [];
console.warn = (m) => warns.push(String(m));
const txt = (t) => ({ type: 'text', text: t });
const item = (title, body, at = '2026-11-21T10:00:00.000Z') => ({ title, body, publishedAt: at });
const older = item('Válidos', [{ type: 'paragraph', children: [txt('ok')] }], '2026-01-01T00:00:00.000Z');
function run(name, body) {
  warns.length = 0;
  const t0 = Date.now();
  try {
    const r = parseTerms({ data: [item('Hostil', body), older] });
    const uniq = [...new Set(warns)];
    console.log(`${name}: shown=${r?.title} blocks=${r?.blocks.length} ms=${Date.now() - t0} warnings=${JSON.stringify(uniq).slice(0, 160)}`);
  } catch (e) { console.log(`${name}: THROW ${e.constructor.name} ${e.message.slice(0, 80)}`); }
}
// 1. link nested 200 000 levels
let n = txt('fondo'); for (let i = 0; i < 200000; i++) n = { type: 'link', url: 'javascript:alert(1)', children: [n] };
run('link x200000', [{ type: 'paragraph', children: [n] }]);
// 2. link nested 2 levels with text at both levels
run('link>link mixed', [{ type: 'paragraph', children: [{ type: 'link', url: 'https://x.invalid', children: [txt('uno'), { type: 'link', url: 'y', children: [txt('dos')] }] }] }]);
// 3. 1 000 000 headings
const h = new Array(1000000); for (let i = 0; i < h.length; i++) h[i] = { type: 'heading', level: 1 + (i % 6), children: [txt('t')] };
run('headings x1e6', h);
// 4. list nested 200 000 levels via list-in-list
let l = { type: 'list', format: 'ordered', children: [{ type: 'list-item', children: [txt('hoja')] }] };
for (let i = 0; i < 200000; i++) l = { type: 'list', format: 'unordered', children: [{ type: 'list-item', children: [txt('n')] }, l] };
run('list x200000', [l]);
// 5. list-item containing a list-item containing link chain
run('list-item>link x200000', [{ type: 'list', format: 'unordered', children: [{ type: 'list-item', children: [n] }] }]);
// 6. 1 000 000 inline text children in one paragraph
const kids = new Array(1000000); for (let i = 0; i < kids.length; i++) kids[i] = txt('a');
run('paragraph 1e6 spans', [{ type: 'paragraph', children: kids }]);
// 7. a link whose children is a huge array
run('link 1e6 children', [{ type: 'paragraph', children: [{ type: 'link', url: 'u', children: kids }] }]);
// 8. heading levels as -0, NaN, Infinity, 1e308
run('heading odd levels', [-0, NaN, Infinity, 1e308, '1', null].map((lv) => ({ type: 'heading', level: lv, children: [txt('x')] })).concat([{ type: 'paragraph', children: [txt('p')] }]));
// 9. children not arrays / proto keys
run('weird', JSON.parse('[{"type":"paragraph","children":{"length":3}},{"__proto__":{"type":"paragraph"},"children":[]},{"type":"paragraph","children":[{"type":"text","text":"<img src=x onerror=alert(1)>","__proto__":{"bold":true}}]}]'));
// 10. top-level body not array, deep nested arrays
let a = []; for (let i = 0; i < 200000; i++) a = [a];
run('nested arrays', a);
EOF
cd $S && node run.mjs

